    @Transactional(noRollbackFor = UnauthorizedException.class)
    public LoginResponse login(LoginRequest request) {
        User user = userRepository.findByUsername(request.getUsername())
                .orElseThrow(() -> new UnauthorizedException(BAD_CREDENTIALS));

        ensureUserCanAttemptLogin(user);

        try {
            authenticationManager.authenticate(
                    new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword()));
        } catch (AuthenticationException e) {
            boolean locked = recordFailedLogin(user);
            if (locked) {
                throw new UnauthorizedException(ACCOUNT_LOCKED_PREFIX + lockDurationSeconds + " second(s)");
            }
            throw new UnauthorizedException(BAD_CREDENTIALS);
        }

        resetFailedLoginState(user);

        String accessToken = jwtUtil.generateToken(user.getUsername(), user.getId(), user.getRole());
        RefreshToken refreshToken = createRefreshToken(user.getId());

        logger.info("User logged in: {}", user.getUsername());
        return new LoginResponse(
                accessToken,
                refreshToken.getToken(),
                jwtUtil.getExpiration(),
                user.getUsername(),
                user.getEmail(),
                user.getRole());
    }
```

